// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.math.BigInteger;
import java.util.Random;

import org.junit.jupiter.api.Test;

class AsyncValueRetirementRemainingCountTest {
	private static final BigInteger MAXIMUM = BigInteger.valueOf(Long.MAX_VALUE);

	@Test
	void saturatedCountReturnsToItsExactValueAfterAcknowledgement() {
		var count = new AsyncValueRetirementCoordinator.RemainingCount();
		assertEquals(0L, count.saturatedValue());
		count.add(Long.MAX_VALUE);
		count.add(10L);
		assertEquals(Long.MAX_VALUE, count.saturatedValue());
		count.subtract(11L);
		assertEquals(Long.MAX_VALUE - 1L, count.saturatedValue());
		count.subtract(Long.MAX_VALUE - 1L);
		assertEquals(0L, count.saturatedValue());
	}

	@Test
	void unsignedWrapAndBorrowPreserveTheExactOutstandingTotal() {
		var count = new AsyncValueRetirementCoordinator.RemainingCount();
		BigInteger expected = BigInteger.ZERO;
		expected = add(count, expected, Long.MAX_VALUE);
		expected = add(count, expected, Long.MAX_VALUE);
		expected = add(count, expected, 2L); // Exactly 2^64: a zero low word must still appear saturated.
		expected = subtract(count, expected, 1L);
		expected = subtract(count, expected, Long.MAX_VALUE);
		expected = subtract(count, expected, 1L);
		expected = subtract(count, expected, Long.MAX_VALUE);
		assertEquals(BigInteger.ZERO, expected);
	}

	@Test
	void multipleCarriesCanBeFullyDrainedAndTheCounterReused() {
		var count = new AsyncValueRetirementCoordinator.RemainingCount();
		BigInteger expected = BigInteger.ZERO;
		for (int i = 0; i < 257; i++) {
			expected = add(count, expected, Long.MAX_VALUE);
		}
		for (int i = 0; i < 257; i++) {
			expected = subtract(count, expected, Long.MAX_VALUE);
		}
		assertEquals(BigInteger.ZERO, expected);
		expected = add(count, expected, 17L);
		expected = subtract(count, expected, 17L);
		assertEquals(BigInteger.ZERO, expected);
	}

	@Test
	void seededValidInterleavingsMatchAnIndependentBigIntegerTotal() {
		var count = new AsyncValueRetirementCoordinator.RemainingCount();
		Random random = new Random(0x524446344AL);
		long[] boundaries = { 0L, 1L, 2L, (1L << 32) - 1L, 1L << 32, Long.MAX_VALUE - 1L,
				Long.MAX_VALUE };
		BigInteger expected = BigInteger.ZERO;
		for (int i = 0; i < 8192; i++) {
			long amount = (i & 7) == 0 ? boundaries[random.nextInt(boundaries.length)]
					: random.nextLong() & Long.MAX_VALUE;
			if (expected.signum() == 0 || random.nextBoolean()) {
				expected = add(count, expected, amount);
			} else {
				amount = Math.min(amount, expected.min(MAXIMUM).longValueExact());
				expected = subtract(count, expected, amount);
			}
			if ((i & 63) == 63) {
				// Return below saturation repeatedly, making any hidden carry/borrow error observable.
				while (expected.signum() != 0) {
					expected = subtract(count, expected, expected.min(MAXIMUM).longValueExact());
				}
			}
		}
		assertEquals(BigInteger.ZERO, expected);
		assertEquals(0L, count.saturatedValue());
	}

	private static BigInteger add(AsyncValueRetirementCoordinator.RemainingCount count, BigInteger expected,
			long amount) {
		count.add(amount);
		BigInteger result = expected.add(BigInteger.valueOf(amount));
		assertEquals(result.min(MAXIMUM).longValueExact(), count.saturatedValue());
		return result;
	}

	private static BigInteger subtract(AsyncValueRetirementCoordinator.RemainingCount count, BigInteger expected,
			long amount) {
		count.subtract(amount);
		BigInteger result = expected.subtract(BigInteger.valueOf(amount));
		assertEquals(result.min(MAXIMUM).longValueExact(), count.saturatedValue());
		return result;
	}
}
